head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "ULDSTF08033";
scwin.isurCd = "";          // 발행기관코드 (AS-IS arr[0] Isur_cd)
scwin.isurNm = "";          // 발행기관명 (AS-IS arr[1] Isur_nm)
scwin.secugrpId = "";       // 증권그룹ID (AS-IS arr[2] Secugrp_id)
scwin.mktId = "";           // 시장구분코드 (AS-IS arr[3] Mkt_id)
scwin.bzProcsNo = "";       // 업무처리번호 (AS-IS arr[4] fr_bz_procs_no) — 비면 신규. 저장 뒤 응답 번호로 바뀐다
scwin.tpCd = "";            // 관리종목지정업무구분코드 (AS-IS arr[5] tpCd) — 이 화면은 4: 해제
scwin.isuCd = "";           // 종목코드 (AS-IS arr[6] Isu_cd)
scwin.selTp = "";           // 선택 구분 0: 형제 팝업에서 옴, 1: 종목, 2: 발행회사, 3: 전체 (AS-IS arr[7] gubun)
scwin.orgBzProcsNo = "";    // 원 지정업무처리번호 (AS-IS arr[8] fr_org_bz_procs_no)
scwin.todayDd = "";         // 오늘 (yyyyMMdd) — 해제일 익일 이후 검사
scwin.trJob = "";           // 처리구분 I: 저장, U: 수정, D: 삭제
scwin.isSaved = false;      // 저장·수정에 한 번이라도 성공하면 true — 부모 재조회 표시
scwin.TP_CD_RELEAS = "4";                                       // 관리종목지정업무구분코드 4: 해제
scwin.DSCL_FORM_CD = "68345";                                   // 공시안내문 서식 — 관리종목지정 해제
scwin.DEFAULT_GRND_REGUL = "유가증권시장상장규정 제149조의6제2항";   // 해제 근거규정 기본값 (AS-IS txb_RelAdmisuDesignGrndRegulNm value)
scwin.RESULT_FAIL = "F";                                        // 등록·수정·삭제 응답 result 의 실패 값 (명세 S:성공, F:실패)
// 원본 : /etn/ULDSTF08033.gfm (ETN 관리종목지정 해제 팝업)
/*
 * 화면 동작
 *  - 부모(ULDSTF08031 목록, 또는 08032·08032_new·08034 의 [해제] — 부모 경유)가 넘긴 업무처리번호가 없으면 신규, 있으면 상세를 조회해 수정 모드로 연다.
 *  - 신규는 원 지정 건(지정업무처리번호)의 지정일·근거규정·기타와 종목을 보여 주고, 해제일·해제사유·근거규정을 입력해 등록한다(서버 채번).
 *  - 저장·수정에 성공하면 isSaved 를 남기고 다시 조회한다. 삭제에 성공하면 closePopup({ isSaved : true }) 로 닫는다.
 *    부모는 isSaved || isCloseButtonClick 이면 목록을 다시 조회한다(원본 fn_parentRefresh 대체 — 공통 계약서 §3).
 *  - 공시안내문작성(ULDSTF92024)은 openPopup 의 data 로 넘기고 await 한다. 92024 전환본이 아직 부모 getPar 를 부르므로 호환용 scwin.getPar 를 둔다.
 * API 명세 : conversion/conversion-front/ui/completed/ULDSTF08031/ULDSTF08031,ULDSTF08032,ULDSTF08032_new,ULDSTF08033,ULDSTF08033_new,ULDSTF08034,ULDSTF08037_API.md (공용)
 * 선언 순서 : 부모 화면에서 넘겨받는 값(§1.2 — 공통 계약서 §3.1, arr 0~8) → 화면 상태값 → 고정값.
 * 업무 분석 : conversion/conversion-front/ui/completed/ULDSTF08033/ULDSTF08033.md (§번호는 이 문서의 절)
 */

// 이 화면의 역할→버튼 매핑 — 상태별 활성 정책은 공통(BTN_STATE_MAP)이 보유한다.
scwin.BTN_MAP = {
    save : "btn_Save",          // [저장]
    modify : "btn_Update",      // [수정]
    "delete" : "btn_Delete",    // [삭제]
    guide : "btn_Dscl"          // [안내문작성]
};

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name scwin.onpageload
 * @author Inswave
 * @date 2026. 10. 30
 * @description 페이지로드. 로딩 로직은 scwin.init 하나에 둔다(code-convention 초기화 절). (§3)
 * @returns
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        await scwin.init();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF08033.onpageload" });
    }
};

/**
 * @method
 * @name scwin.init
 * @author Inswave
 * @date 2026. 10. 30
 * @description 로딩 — 버튼 잠금 → 파라미터 수신 → 오늘 → 달력 바인딩 → 상세 조회(신규는 원 지정 건 기준) → 지정사유 조회. (원본 gform onload — §3)
 * @returns
 * @hidden N
 */
scwin.init = async function () {
    // 1) 로딩 동안 버튼 잠금 — 조회가 예외로 끝나도 버튼이 XML 기본값(전부 활성)으로 남지 않게 한다.
    $c.util.setButtonState("grpBtnBox", "disabled", scwin.BTN_MAP);

    // 2) 파라미터 수신 — 원본 frame.Provider("../").fn_GetPar(arrPar) (§1.2)
    const param = $c.data.getParameter() ?? {};

    scwin.isurCd = String(param.isurCd ?? "");
    scwin.isurNm = String(param.isurNm ?? "");
    scwin.secugrpId = String(param.secugrpId ?? "");
    scwin.mktId = String(param.mktId ?? "");
    scwin.bzProcsNo = String(param.bzProcsNo ?? "");
    scwin.tpCd = String(param.admisuDesignBzTpCd ?? "");
    scwin.isuCd = String(param.isuCd ?? "");
    scwin.selTp = String(param.selTp ?? "");
    scwin.orgBzProcsNo = String(param.admisuDesignBzProcsNo ?? "");

    // 3) 오늘 — 해제일 익일 이후 검사(원본 checkDdTm 의 현재일)
    scwin.todayDd = $c.date.getServerDateTime("yyyyMMdd");

    // 4) 달력 검사 바인딩(1회) — 단일 달력 (규칙 37). 지정일은 읽기 전용 표시지만 형식은 같다.
    $c.date.checkCalendarFormat(edt_MktactEnforceDd, "yyyyMMdd");
    $c.date.checkCalendarFormat(edt_MktactEnforceEndDd, "yyyyMMdd");

    // 5) 상세 → 지정사유 (원본 fn_search / fn_new_onload 다음 fn_search_rsn)
    await scwin.selectDetail();
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name scwin.btn_Save_onclick
 * @author Inswave
 * @date 2026. 10. 30
 * @description 저장 버튼 클릭
 * @param {Object} e 이벤트 객체
 * @returns
 * @hidden N
 */
scwin.btn_Save_onclick = async function (e) {
    try {
        await scwin.save();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF08033.btn_Save_onclick" });
    }
};

/**
 * @method
 * @name scwin.btn_Update_onclick
 * @author Inswave
 * @date 2026. 10. 30
 * @description 수정 버튼 클릭
 * @param {Object} e 이벤트 객체
 * @returns
 * @hidden N
 */
scwin.btn_Update_onclick = async function (e) {
    try {
        await scwin.update();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF08033.btn_Update_onclick" });
    }
};

/**
 * @method
 * @name scwin.btn_Delete_onclick
 * @author Inswave
 * @date 2026. 10. 30
 * @description 삭제 버튼 클릭
 * @param {Object} e 이벤트 객체
 * @returns
 * @hidden N
 */
scwin.btn_Delete_onclick = async function (e) {
    try {
        await scwin.remove();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF08033.btn_Delete_onclick" });
    }
};

/**
 * @method
 * @name scwin.btn_Dscl_onclick
 * @author Inswave
 * @date 2026. 10. 30
 * @description 안내문작성 버튼 클릭
 * @param {Object} e 이벤트 객체
 * @returns
 * @hidden N
 */
scwin.btn_Dscl_onclick = async function (e) {
    try {
        await scwin.writeDscl();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF08033.btn_Dscl_onclick" });
    }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name scwin.selectDetail
 * @author Inswave
 * @date 2026. 10. 30
 * @description 상세 조회(묶음). 해제 건 마스터·원 지정 건 마스터·종목내역을 한 번에 받는다. 업무처리번호가 없으면(신규) 원 지정 건 기준으로
 * 지정 정보와 종목만 받고 해제 입력 폼을 새로 준비한다. 이어서 지정사유를 조회하고 버튼 상태를 정한다.
 * (원본 fn_search · fn_new_onload + dts_Mst·dts_Isu OnLoadCompleted — §5.1)
 * @returns
 * @hidden N
 */
scwin.selectDetail = async function () {
    const sbmOptions = {
        id : "sbm_selectDetail",
        method : "get",
        action : "/api/listing/lstproc/etn/adm-isu/select-one",
        isProcessMsg : false
    };

    const requestData = {
        bzProcsNo : scwin.bzProcsNo,            // AS-IS BZ_PROCS_NO (dts_Mst) — 신규는 빈 값
        orgBzProcsNo : scwin.orgBzProcsNo,      // AS-IS BZ_PROCS_NO (dts_Mst_Bf) = fr_org_bz_procs_no
        isurCd : scwin.isurCd                   // AS-IS ISUR_CD (dts_Isu, DIV_IDX ISU_ITM)
    };

    const result = await $c.sbm.executeDynamic(sbmOptions, requestData);
    if (result?.skipped) return;    // 진행 중 조회가 있어 이번 호출은 건너뜀

    // 실패하면 버튼을 잠근 채 둔다(init 1단계) — 신규 상태로 오인해 다시 등록하지 않게.
    if (!result.responseJSON?.success) return;

    const body = result.responseJSON.body ?? {};

    // 명세 [RESPONSE & 처리] — 업무처리번호가 없으면 mst·mstBf 는 null
    dma_packageMstBf.setEmptyValue();
    if (body.mstBf) dma_packageMstBf.setJSON(body.mstBf);
    dlt_packageIsuList.setJSON(body.isuList ?? []);

    // 종목코드 — 부모가 넘긴 값 우선, 없으면 등록된 종목(selected T) → 첫 행 (AS-IS dts_Isu OnLoadCompleted 의 Isu_cd)
    if ($c.util.isEmpty(scwin.isuCd) && dlt_packageIsuList.getRowCount() > 0) {
        scwin.isuCd = dlt_packageIsuList.getCellData(scwin.getIsuRow(), "isuCd");
    }

    if ($c.util.isEmpty(scwin.bzProcsNo) || !body.mst) {
        scwin.initNewForm();
    } else {
        dma_packageMst.setEmptyValue();
        dma_packageMst.setJSON(body.mst);
    }

    await scwin.selectRsn();
    scwin.setButtonByDetail();
};

/**
 * @method
 * @name scwin.selectRsn
 * @author Inswave
 * @date 2026. 10. 30
 * @description 해제 대상 지정사유 조회 — 그 종목의 최신 지정 건 사유 목록. (원본 fn_search_rsn, DIV_IDX RSN_BF·TRS_IDX NEWSEL2 — §5.2)
 * @returns
 * @hidden N
 */
scwin.selectRsn = async function () {
    const sbmOptions = {
        id : "sbm_selectRsn",
        method : "get",
        action : "/api/listing/lstproc/etn/adm-isu/select-list-rsn-new2",
        target : "dlt_listRsnNew2=body",
        isProcessMsg : false
    };

    dlt_listRsnNew2.removeAll();
    if ($c.util.isEmpty(scwin.isuCd)) return;

    await $c.sbm.executeDynamic(sbmOptions, { isuCd : scwin.isuCd });    // AS-IS ISU_CD (ISUR_CD 는 명세에 없음)
};

/**
 * @method
 * @name scwin.checkDoubleInput
 * @author Inswave
 * @date 2026. 10. 30
 * @description 업무 중복입력 체크 — 같은 종목·같은 해제일로 이미 입력된 건(자기 건 제외)이 있으면 안내하고 false. (원본 fn_check_bz_doubleinput_etn — §5.3)
 * @returns {Promise<Boolean>} 중복이 없으면 true
 * @hidden N
 */
scwin.checkDoubleInput = async function () {
    const sbmOptions = {
        id : "sbm_checkDoubleInput",
        method : "get",
        action : "/api/listing/lstproc/etn/adm-isu/check-double-input",
        target : "dma_checkDoubleInput=body",
        isProcessMsg : false
    };

    const requestData = {
        isuCd : scwin.isuCd,                                        // AS-IS Isu_cd
        mktactEnforceDd : dma_packageMst.get("mktactEnforceDd"),    // AS-IS getObjectValue(edt_MktactEnforceEndDd)
        bzProcsNo : scwin.bzProcsNo                                 // AS-IS fr_bz_procs_no — 자기 건 제외 (업무구분 713 은 서버 고정)
    };

    dma_checkDoubleInput.setEmptyValue();
    const result = await $c.sbm.executeDynamic(sbmOptions, requestData);
    if (result?.skipped) return false;

    if (!result.responseJSON?.success) {
        await $c.win.alert($c.stf.getMessageParam("MSG-A002", "중복확인"));
        return false;
    }

    if (dma_checkDoubleInput.get("dupYn") === "Y") {
        // 원본(pcc checkBzDoubleInput) 안내 문구 그대로
        await $c.win.alert("[" + dma_checkDoubleInput.get("disclsProcsStatCd") + "]건으로 " + dma_checkDoubleInput.get("disclsProcsDdtm") + "에  이미 입력되어있습니다.");
        return false;
    }
    return true;
};

/**
 * @method
 * @name scwin.checkMstStatus
 * @author Inswave
 * @date 2026. 10. 30
 * @description 종목 최신 처리상태 확인 — 최근 건의 시행일이 해제일보다 앞이어야 하고(MSG-0020), 최근 건이 있으면서 해제가 아니어야 한다(MSG-0021).
 * 명세는 등록 API 가 같은 확인을 서버에서 한다고 적었지만, 원본처럼 저장 전에 안내한다. (원본 fn_getMstStatus_etn — §5.4)
 * @returns {Promise<Boolean>} 저장 가능하면 true
 * @hidden N
 */
scwin.checkMstStatus = async function () {
    const sbmOptions = {
        id : "sbm_checkMstStatus",
        method : "get",
        action : "/api/listing/lstproc/etn/adm-isu/select-one-status",
        target : "dma_oneStatus=body",
        isProcessMsg : false
    };

    dma_oneStatus.setEmptyValue();
    const result = await $c.sbm.executeDynamic(sbmOptions, { isuCd : scwin.isuCd });
    if (result?.skipped) return false;

    if (!result.responseJSON?.success) {
        await $c.win.alert($c.stf.getMessageParam("MSG-A002", "처리상태 확인"));
        return false;
    }

    // 최근 건 시행일 >= 해제일 이면 처리 불가
    const lastDd = String(dma_oneStatus.get("mktactEnforceDd") ?? "");
    if (!$c.util.isEmpty(lastDd) && lastDd >= dma_packageMst.get("mktactEnforceDd")) {
        await $c.win.alert($c.stf.getMessageParam("MSG-0020", ""));
        return false;
    }

    // 해제는 직전 건이 있고 해제가 아니어야 한다 (원본 tpCd 4 분기)
    const lastTpCd = String(dma_oneStatus.get("admisuDesignBzTpCd") ?? "");
    if ($c.util.isEmpty(lastTpCd) || lastTpCd === scwin.TP_CD_RELEAS) {
        await $c.win.alert($c.stf.getMessageParam("MSG-0021", ""));
        return false;
    }
    return true;
};

/**
 * @method
 * @name scwin.registerTrs
 * @author Inswave
 * @date 2026. 10. 30
 * @description 신규 등록(단건). 업무처리번호를 비워 서버가 채번하고, 원 지정업무처리번호를 함께 보낸다.
 * (원본 fn_save 의 fn_getNewBzProcNo + fn_save_trs(TRS_IDX_INSERT) — §5.5)
 * @returns {Promise<Boolean|null>} 성공 true, 실패 false, 중복 실행 건너뜀 null
 * @hidden N
 */
scwin.registerTrs = async function () {
    dma_registerReleasMstDto.setEmptyValue();
    dma_registerReleasMstDto.setJSON({ ...scwin.getMstDto(), bzProcsNo : "" });    // 비우면 서버 채번

    const sbmOptions = {
        id : "sbm_registerTrs",
        method : "post",
        action : "/api/listing/lstproc/etn/adm-isu/register-releas",
        target : "dma_resultSave=body",
        mediatype : "application/json",
        isProcessMsg : false
    };

    const requestData = {
        mstDto : dma_registerReleasMstDto.getJSON(),
        isuCdList : []                                  // 비우면 마스터 종목코드 1건 (다건은 08033_new)
    };

    dma_resultSave.setEmptyValue();
    const result = await $c.sbm.executeDynamic(sbmOptions, requestData);
    if (result?.skipped) return null;    // 진행 중 처리가 있어 이번 호출은 건너뜀

    return scwin.isSaveSuccess(result);
};

/**
 * @method
 * @name scwin.modifyTrs
 * @author Inswave
 * @date 2026. 10. 30
 * @description 해제 수정. (원본 fn_update 의 fn_save_trs(TRS_IDX_UPDATE) — §5.6)
 * @returns {Promise<Boolean|null>} 성공 true, 실패 false, 중복 실행 건너뜀 null
 * @hidden N
 */
scwin.modifyTrs = async function () {
    dma_modifyReleasMstDto.setEmptyValue();
    dma_modifyReleasMstDto.setJSON(scwin.getMstDto());

    const sbmOptions = {
        id : "sbm_modifyTrs",
        method : "post",
        action : "/api/listing/lstproc/etn/adm-isu/modify-releas",
        target : "dma_resultSave=body",
        mediatype : "application/json",
        isProcessMsg : false
    };

    const requestData = {
        mstDto : dma_modifyReleasMstDto.getJSON(),
        isuCdList : []
    };

    dma_resultSave.setEmptyValue();
    const result = await $c.sbm.executeDynamic(sbmOptions, requestData);
    if (result?.skipped) return null;

    return scwin.isSaveSuccess(result);
};

/**
 * @method
 * @name scwin.removeTrs
 * @author Inswave
 * @date 2026. 10. 30
 * @description 해제 삭제 — 업무처리번호만 보낸다. 시장안내공시가 승인된 건은 서버가 거부한다(원본 fn_check_delete_discls 대체). (원본 fn_delete — §5.7)
 * @returns {Promise<Boolean|null>} 성공 true, 실패 false, 중복 실행 건너뜀 null
 * @hidden N
 */
scwin.removeTrs = async function () {
    const sbmOptions = {
        id : "sbm_removeTrs",
        method : "post",
        action : "/api/listing/lstproc/etn/adm-isu/remove",
        target : "dma_resultSave=body",
        mediatype : "application/json",
        isProcessMsg : false
    };

    dma_resultSave.setEmptyValue();
    const result = await $c.sbm.executeDynamic(sbmOptions, { bzProcsNo : scwin.bzProcsNo });
    if (result?.skipped) return null;

    return scwin.isSaveSuccess(result);
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name scwin.initNewForm
 * @author Inswave
 * @date 2026. 10. 30
 * @description 신규 준비 — 해제 입력 폼을 비우고 발행기관·근거규정 기본값을 넣는다. 통신 없음. (원본 dts_Mst OnLoadCompleted 신규 분기 — §3, §6.1)
 * @returns
 * @hidden N
 */
scwin.initNewForm = function () {
    dma_packageMst.setEmptyValue();
    dma_packageMst.set("isurCd", scwin.isurCd);
    dma_packageMst.set("isuCd", scwin.isuCd);
    dma_packageMst.set("admisuDesignBzTpCd", scwin.TP_CD_RELEAS);
    dma_packageMst.set("admisuDesignBzProcsNo", scwin.orgBzProcsNo);
    dma_packageMst.set("grndRegulNm", scwin.DEFAULT_GRND_REGUL);
};

/**
 * @method
 * @name scwin.setButtonByDetail
 * @author Inswave
 * @date 2026. 10. 30
 * @description 버튼 상태 — 신규는 저장만, 수정은 해제일이 오늘 이후면 수정·삭제·안내문작성, 지났으면 잠금. 단 공시 전(dscYn ≠ Y)이면 수정 가능.
 * (원본 buttonSet.setInsertStatus / setButtonSetWithDate(해제일, false) + setButtonSetWithDate2(DSC_YN) — §6.2)
 * @returns
 * @hidden N
 */
scwin.setButtonByDetail = function () {
    if ($c.util.isEmpty(scwin.bzProcsNo)) {
        $c.util.setButtonState("grpBtnBox", "insert", scwin.BTN_MAP);
        return;
    }
    $c.stf.setButtonSetWithDate(edt_MktactEnforceEndDd, false, "grpBtnBox", scwin.BTN_MAP);
    $c.stf.setButtonSetWithDate2(dma_packageMst.get("dscYn"), "grpBtnBox", scwin.BTN_MAP);
};

/**
 * @method
 * @name scwin.getIsuRow
 * @author Inswave
 * @date 2026. 10. 30
 * @description 대상 종목 행 — 화면 종목코드와 같은 행, 없으면 등록된 종목(selected T), 그것도 없으면 첫 행. (원본 dts_Isu.RowPosition — §6.3)
 * @returns {Number} 행 index (종목이 없으면 -1)
 * @hidden N
 */
scwin.getIsuRow = function () {
    const rows = dlt_packageIsuList.getAllJSON();
    if (rows.length === 0) return -1;

    let row = rows.findIndex(item => !$c.util.isEmpty(scwin.isuCd) && item.isuCd === scwin.isuCd);
    if (row < 0) row = rows.findIndex(item => item.selected === "T");
    return (row < 0) ? 0 : row;
};

/**
 * @method
 * @name scwin.getMstDto
 * @author Inswave
 * @date 2026. 10. 30
 * @description 등록·수정 요청 마스터 — 해제 입력 폼 + 화면 상태값. (원본 fn_save 의 dts_Mst NameString 대입 — §5.5·§5.6)
 * @returns {Object} mstDto
 * @hidden N
 */
scwin.getMstDto = function () {
    return {
        bzProcsNo : scwin.bzProcsNo,                                    // AS-IS BZ_PROCS_NO
        isuCd : scwin.isuCd,                                            // AS-IS ISU_CD
        mktactEnforceDd : dma_packageMst.get("mktactEnforceDd"),        // 해제일 (AS-IS MKTACT_ENFORCE_DD)
        grndRegulNm : dma_packageMst.get("grndRegulNm"),                // 근거규정 (AS-IS GRND_REGUL_NM)
        admisuRsnContn : dma_packageMst.get("admisuRsnContn"),          // 해제사유 (AS-IS ADMISU_RSN_CONTN)
        admisuDesignBzProcsNo : scwin.orgBzProcsNo,                     // 원 지정업무처리번호 (AS-IS ADMISU_DESIGN_BZ_PROCS_NO)
        remk : dma_packageMst.get("remk")                               // 비고 (원본도 입력 칸 없음 — 조회값 그대로)
    };
};

/**
 * @method
 * @name scwin.validate
 * @author Inswave
 * @date 2026. 10. 30
 * @description 저장·수정 전 입력 검증. 원본 fn_CheckForm 순서 — 해제일 필수·날짜·익일 이후 → 해제사유 필수·2000 byte → 근거규정 필수·200 byte → 업무 중복입력.
 * (pcc checkDdTm 은 Gauce 속성 .text 를 읽어 쓰지 않는다 — §6.4)
 * @returns {Promise<Boolean>} 검증 통과 여부
 * @hidden N
 */
scwin.validate = async function () {
    const dateOptions = {
        validateType : "alert",     // alert|mark|all
        checkType : "single",       // single|multi
        fields : {
            edt_MktactEnforceEndDd : { required : true, format : "date", name : "해제일" }
        }
    };
    if (!await $c.validate.validateDataCollect(panel_2, dateOptions)) return false;

    // 해제일은 익일 이후 (원본 checkDdTm("DD", edt_MktactEnforceEndDd, "해제", false))
    if (dma_packageMst.get("mktactEnforceDd") <= scwin.todayDd) {
        await $c.win.alert("[해제일]을 익일 이후로 입력하세요.");
        edt_MktactEnforceEndDd.focus();
        return false;
    }

    const etcOptions = {
        validateType : "alert",
        checkType : "single",
        fields : {
            txa_RelRsnContn : { required : true, maxLengthB : 2000, name : "해제사유" },
            txb_RelAdmisuDesignGrndRegulNm : { required : true, maxLengthB : 200, name : "근거규정" }
        }
    };
    if (!await $c.validate.validateDataCollect(panel_2, etcOptions)) return false;

    return await scwin.checkDoubleInput();
};

/**
 * @method
 * @name scwin.isSaveSuccess
 * @author Inswave
 * @date 2026. 10. 30
 * @description 등록·수정·삭제 응답 판정 — 통신 성공이고 result 가 실패(F)가 아니면 true. (§5.5~5.7)
 * @param {Object} result executeDynamic 결과
 * @returns {Boolean} 성공 여부
 * @hidden N
 */
scwin.isSaveSuccess = function (result) {
    // TODO: result 를 비워 보내는 경우가 있는지 확인 — 지금은 F 만 실패로 본다 (§10 #3)
    return result.responseJSON?.success === true && dma_resultSave.get("result") !== scwin.RESULT_FAIL;
};

/**
 * @method
 * @name scwin.save
 * @author Inswave
 * @date 2026. 10. 30
 * @description 신규 저장. 검증 → 처리상태 확인 → 확인 → 등록. 성공하면 응답 업무처리번호로 다시 조회해 수정 모드로 바꾼다.
 * (원본 fn_save + trs OnSuccess — §6.5, §1.4 업무 2)
 * @returns
 * @hidden N
 */
scwin.save = async function () {
    scwin.trJob = "I";

    if (!await scwin.validate()) return;
    if (!await scwin.checkMstStatus()) return;

    // "[저장] 처리를 하시겠습니까?" — 업무공통 MSG-A006
    if (!await $c.lc.isProcess(scwin.trJob)) return;

    const isSuccess = await scwin.registerTrs();
    if (isSuccess === null) return;

    if (!isSuccess) {
        await $c.win.alert(dma_resultSave.get("resultMessage") || $c.stf.getMessageParam("MSG-A002", "저장"));
        return;
    }

    await $c.win.alert($c.stf.getMessageParam("MSG-A001", "저장"));
    scwin.isSaved = true;

    // 원본: 채번 번호로 다시 조회(fn_search). 응답에 번호가 없으면 수정할 키가 없으므로 닫는다(부모가 재조회).
    const savedNo = String(dma_resultSave.get("bzProcsNo") ?? "");
    if ($c.util.isEmpty(savedNo)) {
        // TODO: 등록 응답에 업무처리번호가 오는지 확인 (§10 #3)
        await $c.win.closePopup({ isSaved : true });
        return;
    }
    scwin.bzProcsNo = savedNo;
    await scwin.selectDetail();
};

/**
 * @method
 * @name scwin.update
 * @author Inswave
 * @date 2026. 10. 30
 * @description 수정. 검증 → 확인 → 수정 → 다시 조회. (원본 fn_update + trs OnSuccess — §6.6, §1.4 업무 3)
 * @returns
 * @hidden N
 */
scwin.update = async function () {
    scwin.trJob = "U";

    if (!await scwin.validate()) return;

    // "[수정] 처리를 하시겠습니까?" — 업무공통 MSG-A006
    if (!await $c.lc.isProcess(scwin.trJob)) return;

    const isSuccess = await scwin.modifyTrs();
    if (isSuccess === null) return;

    if (!isSuccess) {
        await $c.win.alert(dma_resultSave.get("resultMessage") || $c.stf.getMessageParam("MSG-A002", "수정"));
        return;
    }

    await $c.win.alert($c.stf.getMessageParam("MSG-A001", "수정"));
    scwin.isSaved = true;
    await scwin.selectDetail();
};

/**
 * @method
 * @name scwin.remove
 * @author Inswave
 * @date 2026. 10. 30
 * @description 삭제. 확인 → 삭제 → 성공하면 팝업을 닫는다(부모가 재조회). 입력 검증은 하지 않는다. (원본 fn_delete + trs OnSuccess D 분기 — §6.7, §1.4 업무 4)
 * @returns
 * @hidden N
 */
scwin.remove = async function () {
    scwin.trJob = "D";

    // "[삭제] 처리를 하시겠습니까?" — 업무공통 MSG-A006
    if (!await $c.lc.isProcess(scwin.trJob)) return;

    const isSuccess = await scwin.removeTrs();
    if (isSuccess === null) return;

    if (!isSuccess) {
        await $c.win.alert(dma_resultSave.get("resultMessage") || $c.stf.getMessageParam("MSG-A002", "삭제"));
        return;
    }

    await $c.win.alert($c.stf.getMessageParam("MSG-A001", "삭제"));
    await $c.win.closePopup({ isSaved : true });
};

/**
 * @method
 * @name scwin.getDsclData
 * @author Inswave
 * @date 2026. 10. 30
 * @description 공시안내문작성(ULDSTF92024)에 넘길 값. 원본 fn_dscl 이 fn_GetPar 로 채우던 arr 과 데이터셋 3개(종목·마스터·사유)다. (§6.8)
 * @returns {Object} 넘길 data
 * @hidden N
 */
scwin.getDsclData = function () {
    const row = scwin.getIsuRow();
    const isu = (row < 0) ? {} : dlt_packageIsuList.getRowJSON(row);

    return {
        formCd : scwin.DSCL_FORM_CD,            // AS-IS arr[0] "68345"
        bzProcsNo : scwin.bzProcsNo,            // AS-IS arr[1] fr_bz_procs_no
        isurCd : scwin.isurCd,                  // AS-IS arr[2] Isur_cd
        mktId : "1",                            // AS-IS arr[3] '1'
        isuNm : isu.isuNm ?? "",                // AS-IS arr[5] dts_Isu ISU_NM (arr[4] 은 비움)
        isu : dlt_packageIsuList.getAllJSON(),  // AS-IS CopyDataSet(dts_Isu, param_dts_isu)
        // AS-IS CopyDataSet(dts_Mst, param_dts_mst) + COM_NM = dts_Isu COM_NM
        mst : [{ ...dma_packageMst.getJSON(), comNm : isu.comNm ?? "" }],
        rsn : dlt_listRsnNew2.getAllJSON()      // AS-IS CopyDataSet(dts_Rsn, param_dts2)
    };
};

/**
 * @method
 * @name scwin.writeDscl
 * @author Inswave
 * @date 2026. 10. 30
 * @description 공시안내문작성 팝업을 data 로 넘겨 열고 닫힐 때까지 기다린다. 원본도 닫힌 뒤 다시 조회하지 않는다. (원본 fn_dscl — §6.8, 가이드 §6.5)
 * @returns
 * @hidden N
 */
scwin.writeDscl = async function () {
    const options = {
        id : "ULDSTF92024",
        popupName : "공시안내문작성",
        width : 745,
        height : 825,
        type : "pageFramePopup"
    };

    // TODO: 경로는 가정, 92024 는 아직 getPar 계약이라 수신부 변경 필요 (§10 #6)
    await $c.win.openPopup("/ui/listingcommon/ULDSTF92024.xml", options, scwin.getDsclData());
};

/**
 * @method
 * @name scwin.getPar
 * @author Inswave
 * @date 2026. 10. 30
 * @description [호환용 · 임시] 공시안내문작성(ULDSTF92024) 전환본은 아직 부모의 scwin.getPar 를 이름으로 불러 값을 받는다.
 * 92024 가 $c.data.getParameter() 수신으로 바뀌면 이 함수를 지운다. (§6.8, §10 #6, 가이드 §6.5 예외)
 * @param {Array} arr 92024 가 넘기는 빈 배열 — [0] 서식코드 [1] 업무처리번호 [2] 발행기관코드 [3] 시장구분 [5] 종목명 을 채운다(원본처럼 [4] 는 비움)
 * @param {Object} dltIsu 92024 의 종목 dataList
 * @param {Object} dltMst 92024 의 마스터 dataList
 * @param {Object} dlt2 92024 의 원천 자료 2 (지정사유)
 * @returns {Number} arr 길이
 * @hidden N
 */
scwin.getPar = function (arr, dltIsu, dltMst, dlt2) {
    const data = scwin.getDsclData();

    arr[0] = data.formCd;
    arr[1] = data.bzProcsNo;
    arr[2] = data.isurCd;
    arr[3] = data.mktId;
    arr[5] = data.isuNm;

    scwin.fillDataList(dltIsu, data.isu);
    scwin.fillDataList(dltMst, data.mst);
    scwin.fillDataList(dlt2, data.rsn);

    return arr.length;
};

/**
 * @method
 * @name scwin.fillDataList
 * @author Inswave
 * @date 2026. 10. 30
 * @description 컬럼 정의가 비어 있는 다른 화면의 dataList 에 행을 채운다. setJSON 은 선언된 컬럼만 옮기므로 첫 행의 키로 컬럼을 먼저 만든다.
 * (92024 의 원천 자료 dataList 는 서식마다 컬럼이 달라 부모가 컬럼째 넘긴다 — 원본 CopyDataSet)
 * @param {Object} dataList 채울 dataList (없으면 무시)
 * @param {Array} rows 넣을 행 목록
 * @returns
 * @hidden N
 */
scwin.fillDataList = function (dataList, rows) {
    if (!dataList) return;

    Object.keys(rows[0] ?? {}).forEach(key => {
        if (dataList.getColumnIndex(key) < 0) dataList.insertColumn(key);
    });
    dataList.setJSON(rows);
};
